event.js.to:
// Keep the allocated callback independent of the asynchronously installed
// native event descriptor. Both rejection and early cancellation own it.
const handlerId = transformCallback(handler);
try {
    const eventId = await invoke('plugin:event|listen', {
        event,
        target,
        handler: handlerId
    });
    return async () => {
        window.__TAURI_INTERNALS__.unregisterCallback(handlerId);
        await _unlisten(event, eventId);
    };
} catch (error) {
    window.__TAURI_INTERNALS__.unregisterCallback(handlerId);
    throw error;
}

